import csv
import io

class Total:
    def __init__(self):
        self.amount = 0

    def add(self, amount):
        self.amount += amount

    def __format__(self, spec):
        return format(self.amount, spec)

totals:dict[str,Total] = {}
accepted:int = 0
source = io.StringIO('kind,amount\nred,3\nblue,2\nred,-1\nblue,5\n')
for row in csv.DictReader(source):
    amount = int(row['amount'])
    if amount >= 0:
        kind = row['kind']
        if kind not in totals:
            totals[kind] = Total()
        totals[kind].add(amount)
        accepted += 1
target = io.StringIO()
target.write('kind,total\n')
for kind in sorted(totals):
    target.write(f'{kind},{totals[kind]:04d}\n')
print(target.getvalue(), end='')
print(accepted)
